function newGame(){score=0;level=1;lives=3;special=3;resetLevel();state='play';beep(650,.1)}
function resetLevel(){ship={x:15,y:65};bullets=[];enemies=[];shots=[];pickups=[];particles=[];boss=null;bossDone=false;time=0;spawn=.5;fire=0;invul=2;transition=0}
function save(){high=Math.max(high,score);try{localStorage.setItem('impact-best',high)}catch{}}
