function damage(){if(invul>0)return;lives--;invul=2;burst(ship.x+4,ship.y+3);beep(100,.2);if(lives<=0){save();state='over';held.clear()}}
function specialWeapon(){if(state!=='play'||special<=0)return;special--;shots=[];enemies.forEach(e=>{burst(e.x,e.y);score+=30});enemies=[];if(boss){boss.hp-=15;burst(boss.x,boss.y)}beep(140,.3);transition=.15}
function impactAction(k){if(k==='power'){if(state==='off'){state='menu';document.querySelector('.phone').classList.remove('off')}else{state='off';held.clear();document.querySelector('.phone').classList.add('off')}return}if(state==='off')return;if(k==='0'){sound=!sound;beep();return}if(k==='star'){specialWeapon();return}if(state==='menu'){if(['2','up','8','down'].includes(k)){selection=1-selection;beep(320)}if(['ok','5'].includes(k)){if(selection===0)newGame();else state='help'}return}if(state==='help'){if(['ok','5','back'].includes(k))state='menu';return}if(state==='over'||state==='win'){if(['ok','5'].includes(k))newGame();if(k==='back')state='menu';return}if(state==='pause'){if(['ok','5','hash'].includes(k))state=pausedFrom;if(k==='back'){save();state='menu'}return}if(['ok','back','hash'].includes(k)){pausedFrom=state;state='pause';held.clear()}}
function impactUpdate(dt){if(state!=='play')return;time+=dt;fire-=dt;invul-=dt;transition=Math.max(0,transition-dt);stars.forEach(s=>{s.x-=s.s*dt;if(s.x<0)s.x=W});let dx=0,dy=0;if(['4','1','7','left'].some(k=>held.has(k)))dx--;if(['6','3','9','right'].some(k=>held.has(k)))dx++;if(['2','1','3','up'].some(k=>held.has(k)))dy--;if(['8','7','9','down'].some(k=>held.has(k)))dy++;const norm=dx&&dy?.707:1;ship.x=Math.max(1,Math.min(175,ship.x+dx*65*dt*norm));ship.y=Math.max(17,Math.min(116,ship.y+dy*65*dt*norm));if(held.has('5')&&fire<=0){bullets.push({x:ship.x+9,y:ship.y+3});fire=.15;beep(780,.025)}
if(time<24){spawn-=dt;if(spawn<=0){spawn=Math.max(.4,1.1-level*.09);enemies.push({x:194,y:23+Math.random()*83,base:23+Math.random()*80,t:0,hp:level>3?2:1,kind:Math.random()>.5?'bug':'fish',shot:1+Math.random()*2})}}else if(!boss&&!bossDone){boss={x:165,y:50,hp:35+level*10,max:35+level*10,t:0,shot:1};beep(180,.4)}
for(const b of bullets)b.x+=145*dt;
for(const e of enemies){e.t+=dt;e.x-=(24+level*5)*dt;e.y=Math.max(18,Math.min(115,e.base+Math.sin(e.t*3)*13));e.shot-=dt;if(e.shot<=0){shots.push({x:e.x,y:e.y+3,vx:-55-level*4,vy:0});e.shot=2}if(Math.abs(e.x-ship.x)<8&&Math.abs(e.y-ship.y)<7){damage();e.hp=0}for(const b of bullets){if(b.x>e.x-2&&b.x<e.x+9&&Math.abs(b.y-e.y-3)<6){e.hp--;b.x=999;if(e.hp<=0){score+=25;burst(e.x,e.y);if(Math.random()<.16)pickups.push({x:e.x,y:e.y,type:Math.random()<.25?'life':'ammo'})}}}}
if(boss){boss.t+=dt;boss.x=Math.max(151,boss.x-dt*5);boss.y=53+Math.sin(boss.t*1.6)*31;boss.shot-=dt;if(boss.shot<=0){for(let a=-1;a<=1;a++)shots.push({x:boss.x,y:boss.y+10,vx:-65-level*4,vy:a*23});boss.shot=Math.max(.45,1.2-level*.08)}for(const b of bullets){if(b.x>=boss.x&&b.x<boss.x+28&&b.y>boss.y&&b.y<boss.y+23){boss.hp--;b.x=999;beep(220,.02)}}if(ship.x+8>boss.x&&ship.y+7>boss.y&&ship.y<boss.y+23)damage();if(boss.hp<=0){score+=500*level;burst(boss.x,boss.y);boss=null;bossDone=true;transition=2.5;shots=[];save()}}
for(const s of shots){s.x+=s.vx*dt;s.y+=s.vy*dt;if(Math.abs(s.x-ship.x-4)<6&&Math.abs(s.y-ship.y-3)<5){s.x=-100;damage()}}for(const p of pickups){p.x-=25*dt;if(Math.abs(p.x-ship.x)<10&&Math.abs(p.y-ship.y)<10){if(p.type==='life')lives=Math.min(5,lives+1);else special=Math.min(9,special+2);p.x=-100;score+=50;beep(950,.1)}}particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.t-=dt});particles=particles.filter(p=>p.t>0);enemies=enemies.filter(e=>e.x>-12&&e.hp>0);bullets=bullets.filter(b=>b.x<W);shots=shots.filter(s=>s.x>-5&&s.y>15&&s.y<H);pickups=pickups.filter(p=>p.x>-10);if(bossDone&&transition<=0&&state==='play'){if(level===8){save();state='win'}else{level++;special=Math.min(9,special+1);resetLevel()}}}
function scene(){stars.forEach(s=>rect(s.x,s.y,1,1));if(invul<=0||Math.floor(invul*10)%2===0)sprite('ship',ship.x,ship.y);bullets.forEach(b=>rect(b.x,b.y,5,1));enemies.forEach(e=>sprite(e.kind,e.x,e.y));shots.forEach(s=>rect(s.x,s.y,2,2));particles.forEach(p=>rect(p.x,p.y,2,2));pickups.forEach(p=>{c.strokeStyle=ink;c.strokeRect(Math.round(p.x),Math.round(p.y),9,9);text(p.type==='life'?'+':'S',p.x+2,p.y+8,8)});if(boss){sprite('bug',boss.x,boss.y,3);rect(128,17,58,2);c.fillStyle=paper;c.fillRect(129+56*boss.hp/boss.max,17,56*(1-boss.hp/boss.max),2)}c.fillStyle=paper;c.fillRect(0,0,W,14);text(String(score).padStart(5,'0'),3,10,9);text('L'+level,85,10,9);text('♥'+lives+' S'+special,188,10,9,'right');rect(0,13,W,1);if(bossDone){panel('SECTOR CLEAR','+500 × '+level,'Next sector...')}else if(transition>0){c.fillStyle=ink;c.fillRect(0,16,W,H-16)}else if(time<2){text('SECTOR '+level,96,40,10,'center')}}
function panel(title,a,b){c.fillStyle=paper;c.fillRect(12,38,168,58);c.strokeStyle=ink;c.strokeRect(13,39,166,56);text(title,96,54,12,'center');text(a,96,71,9,'center');text(b,96,86,8,'center')}
